+        text.push_str(&format!("; note: {}\n", n.replace('\n', " ")));
+    }
+    for w in &warnings {
+        text.push_str(&format!("; warning: {}\n", format!("{w:?}").replace('\n', " ")));
+    }
+    write_golden(&format!("kernel_pocket2d_fig8_{case}.cl"), &text);
