+    assert_eq!(
+        r.row(),
+        "lifts 0 named 0 re 0 | cross 0 leave 0 | entry air 1 hole 0 col 0 solid 0 \
+         (plunge 0 ramp 0 helix 0 rapid 0) | over 0 worst 0 full 0 | fallback 0"
+    );
+    assert_eq!(r.breaks(false), "-");
+}
