+    Pocket3DParams {
+        links: Links::ROUGH3D,
+        tool_diameter: 6.0,
+        stepover: 2.4,
+        stock_to_leave: 0.0,
+        clearance_z: 20.0,
+        top_z: 13.0,
+        bottom_z: 0.0,
+        stepdown: 50.0,
+        feed: 500.0,
+        plunge_feed: 100.0,
+        climb: true,
+        strategy,
+        retract_z: None,
+        entry: Entry3D::Plunge,
+        helix_radius: 1.5,
+        optimal_load: DEFAULT_OPTIMAL_LOAD,
+        pass_start,
+    }
+}
