+/// The points of `of` farther than [`AGREE`] from the paths `from`.
+fn far(of: &[Vec<Point2>], from: &[Vec<Point2>]) -> Vec<Point2> {
+    of.iter().flatten().copied().filter(|q| to_runs(from, *q) > AGREE).collect()
