+fn far_old(old: &[Vec<Point2>], from: &[Vec<Point2>]) -> Vec<Point2> {
+    old.iter().flat_map(|r| r.iter().skip(1)).copied().filter(|q| to_runs(from, *q) > AGREE).collect()
