+    for c in set.curves() {
+        let arc = c.arc().unwrap();
+        assert_eq!((c.family(), c.closed()), (Family::Ring, true));
+        assert!((arc.center().x - 5.0).abs() < 1e-12 && (arc.center().y - 5.0).abs() < 1e-12);
