+        assert!(arc.radius() * (1.0 - (std::f64::consts::PI / n).cos()) <= TOL, "{n} chords for {}", arc.radius());
+        assert!(arc.radius() * (1.0 - (std::f64::consts::PI / (n - 1.0)).cos()) > TOL || n == 8.0, "the least chord count");
+    }
