+    assert_eq!(refused(HelixPlanner.guide(&r, &hole_rings(0.0, 3.0, None), TOL)), NOT_HELIX);
+    let c = Circle::new(p(0.0, 0.0), 5.0).unwrap();
+    assert_eq!(HelixChoice::new(c, 1e-4, 10.0, Hand::Right).unwrap_err().reason(), TOO_MANY_TURNS);
