+const TOL: f64 = 1e-3;
+
+fn chains(chains: Vec<Chain>, keep_out: Region) -> KernelRegion {
+    let sel = Selection::new(chains).unwrap();
+    chain_region(&sel, WorkPlane::setup_xy(0.0).unwrap(), ToolShape::disc(1.0, 0.0, true, 10.0).unwrap(), keep_out).unwrap()
