+
+fn square(x0: f64, y0: f64, s: f64, ccw: bool) -> Chain {
+    let mut v = rect(x0, y0, x0 + s, y0 + s);
+    if !ccw {
+        v.reverse();
+    }
+    Chain::closed(v).unwrap()
